-- ===========================================================================
-- docs/script.sql  |  DONNA CLAUDIA RESTAURANTE E LANCHONETE
-- Modelo relacional: DER logico + Dicionario de Dados recebidos em 08/11/2026.
-- Banco-alvo: MySQL 8.0.16+ (recomendado MySQL 8.0.46 no laboratorio).
-- ===========================================================================
-- ESCOPO ESTRITO: 13 TABELAS DO DIAGRAMA, COM NOMES E COLUNAS DO DICIONARIO:
-- FORNECEDOR, COMPRA, ITEM_COMPRA, PRODUTO, CATEGORIA, ITEM_PEDIDO,
-- PEDIDO, CLIENTE, ENDERECO, PAGAMENTO, ENTREGA, FUNCIONARIO, DESPESA.
-- Nao sao criadas tabelas extras, visoes, procedures ou triggers.
-- Dados 100% ficticios (incluindo clientes, telefones, enderecos e valores).
-- Volume demonstrativo: 900 pedidos em agosto-outubro/2026 (~10/dia).
-- O volume e ficticio e serve somente para demonstracao academica.
-- Os codigos P1-P5, KPI e RN utilizados neste script correspondem ao
-- levantamento e ao README finais do projeto.
-- ATENCAO: DROP DATABASE APAGA TODO O BANCO DE TESTE COM O NOME ABAIXO.
-- NUNCA executar em banco de producao ou com dados importantes.
-- ===========================================================================

-- ETAPA 1: CREATE DATABASE (reproduzivel a partir do zero)
DROP DATABASE IF EXISTS donna_claudia_academico;
CREATE DATABASE donna_claudia_academico CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE donna_claudia_academico;
SET NAMES utf8mb4;

-- ETAPAS 2 e 3: CREATE TABLE + constraints (no proprio CREATE TABLE)
-- Os DECIMAL(10,2) seguem o dicionario; FLOAT foi substituido por DECIMAL
-- para evitar erros de arredondamento de valores monetarios.

CREATE TABLE CATEGORIA (
    id_categoria INT AUTO_INCREMENT PRIMARY KEY,
    nome_categoria VARCHAR(50) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE FORNECEDOR (
    id_fornecedor INT AUTO_INCREMENT PRIMARY KEY,
    nome_empresa VARCHAR(100) NOT NULL UNIQUE,
    contato VARCHAR(100) NULL DEFAULT NULL
) ENGINE=InnoDB;

CREATE TABLE FUNCIONARIO (
    id_funcionario INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    cargo VARCHAR(50) NOT NULL,
    nivel_acesso VARCHAR(20) NOT NULL DEFAULT 'Atendente',
    CONSTRAINT ck_func_nivel CHECK (nivel_acesso IN ('Proprietária', 'Gerente', 'Atendente'))
) ENGINE=InnoDB;

CREATE TABLE CLIENTE (
    id_cliente INT AUTO_INCREMENT PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    telefone VARCHAR(20) NOT NULL,
    telefone_2 VARCHAR(20) NULL DEFAULT NULL
) ENGINE=InnoDB;

CREATE TABLE PRODUTO (
    id_produto INT AUTO_INCREMENT PRIMARY KEY,
    nome_produto VARCHAR(100) NOT NULL UNIQUE,
    descricao VARCHAR(255) NULL DEFAULT NULL,
    preco DECIMAL(10,2) NOT NULL,
    quantidade_estoque INT NOT NULL DEFAULT 0,
    estoque_minimo INT NOT NULL DEFAULT 0,
    id_categoria INT NOT NULL,
    CONSTRAINT fk_produto_categoria FOREIGN KEY (id_categoria) REFERENCES CATEGORIA(id_categoria),
    CONSTRAINT ck_produto_preco CHECK (preco > 0),
    CONSTRAINT ck_produto_estoques CHECK (quantidade_estoque >= 0 AND estoque_minimo >= 0)
) ENGINE=InnoDB;

CREATE TABLE ENDERECO (
    id_endereco INT AUTO_INCREMENT PRIMARY KEY,
    rua VARCHAR(100) NOT NULL,
    numero VARCHAR(10) NOT NULL,
    bairro VARCHAR(50) NOT NULL,
    cep CHAR(8) NOT NULL,
    complemento VARCHAR(50) NULL DEFAULT NULL,
    id_cliente INT NOT NULL,
    CONSTRAINT fk_endereco_cliente FOREIGN KEY (id_cliente) REFERENCES CLIENTE(id_cliente),
    CONSTRAINT ck_endereco_cep CHECK (cep REGEXP '^[0-9]{8}$')
) ENGINE=InnoDB;

CREATE TABLE COMPRA (
    id_compra INT AUTO_INCREMENT PRIMARY KEY,
    data_compra DATE NOT NULL DEFAULT (CURRENT_DATE),
    id_fornecedor INT NOT NULL,
    CONSTRAINT fk_compra_fornecedor FOREIGN KEY (id_fornecedor) REFERENCES FORNECEDOR(id_fornecedor)
) ENGINE=InnoDB;

CREATE TABLE PEDIDO (
    id_pedido INT AUTO_INCREMENT PRIMARY KEY,
    data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    canal_atendimento VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Pendente',
    observacao VARCHAR(255) NULL DEFAULT NULL,
    valor_total DECIMAL(10,2) NOT NULL DEFAULT 0.00,
    motivo_cancelamento VARCHAR(255) NULL DEFAULT NULL,
    id_cliente INT NULL DEFAULT NULL,
    id_funcionario INT NOT NULL,
    CONSTRAINT fk_pedido_cliente FOREIGN KEY (id_cliente) REFERENCES CLIENTE(id_cliente),
    CONSTRAINT fk_pedido_funcionario FOREIGN KEY (id_funcionario) REFERENCES FUNCIONARIO(id_funcionario),
    CONSTRAINT ck_pedido_canal CHECK (canal_atendimento IN ('WhatsApp', 'App', 'Presencial')),
    CONSTRAINT ck_pedido_status CHECK (status IN ('Pendente', 'Em preparo', 'Pronto', 'Em entrega', 'Concluido', 'Cancelado')),
    CONSTRAINT ck_pedido_total CHECK (valor_total >= 0),
    CONSTRAINT ck_pedido_motivo CHECK (status = 'Cancelado' OR motivo_cancelamento IS NULL),
    CONSTRAINT ck_pedido_cliente_canal CHECK (canal_atendimento = 'Presencial' OR id_cliente IS NOT NULL)
) ENGINE=InnoDB;

CREATE TABLE ITEM_COMPRA (
    id_compra INT NOT NULL,
    id_produto INT NOT NULL,
    quantidade INT NOT NULL,
    custo_unitario DECIMAL(10,2) NOT NULL,
    CONSTRAINT pk_item_compra PRIMARY KEY (id_compra, id_produto),
    CONSTRAINT fk_itemcompra_compra FOREIGN KEY (id_compra) REFERENCES COMPRA(id_compra),
    CONSTRAINT fk_itemcompra_produto FOREIGN KEY (id_produto) REFERENCES PRODUTO(id_produto),
    CONSTRAINT ck_itemcompra_qtd CHECK (quantidade > 0),
    CONSTRAINT ck_itemcompra_custo CHECK (custo_unitario > 0)
) ENGINE=InnoDB;

CREATE TABLE ITEM_PEDIDO (
    id_pedido INT NOT NULL,
    id_produto INT NOT NULL,
    quantidade INT NOT NULL,
    preco_unitario DECIMAL(10,2) NOT NULL,
    CONSTRAINT pk_item_pedido PRIMARY KEY (id_pedido, id_produto),
    CONSTRAINT fk_itempedido_pedido FOREIGN KEY (id_pedido) REFERENCES PEDIDO(id_pedido),
    CONSTRAINT fk_itempedido_produto FOREIGN KEY (id_produto) REFERENCES PRODUTO(id_produto),
    CONSTRAINT ck_itempedido_qtd CHECK (quantidade > 0),
    CONSTRAINT ck_itempedido_preco CHECK (preco_unitario > 0)
) ENGINE=InnoDB;

CREATE TABLE PAGAMENTO (
    id_pagamento INT AUTO_INCREMENT PRIMARY KEY,
    forma_pagamento VARCHAR(20) NOT NULL,
    valor DECIMAL(10,2) NOT NULL,
    status_pagamento VARCHAR(20) NOT NULL DEFAULT 'Pendente',
    data_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    id_pedido INT NOT NULL,
    CONSTRAINT fk_pagamento_pedido FOREIGN KEY (id_pedido) REFERENCES PEDIDO(id_pedido),
    CONSTRAINT ck_pagamento_forma CHECK (forma_pagamento IN ('Pix', 'Cartão', 'Dinheiro')),
    CONSTRAINT ck_pagamento_valor CHECK (valor > 0),
    CONSTRAINT ck_pagamento_status CHECK (status_pagamento IN ('Pendente', 'Pago', 'Estornado'))
) ENGINE=InnoDB;

CREATE TABLE ENTREGA (
    id_entrega INT AUTO_INCREMENT PRIMARY KEY,
    status_entrega VARCHAR(20) NOT NULL DEFAULT 'Aguardando',
    data_hora_saida DATETIME NULL DEFAULT NULL,
    data_hora_entrega DATETIME NULL DEFAULT NULL,
    id_pedido INT NOT NULL UNIQUE,
    id_endereco INT NOT NULL,
    CONSTRAINT fk_entrega_pedido FOREIGN KEY (id_pedido) REFERENCES PEDIDO(id_pedido),
    CONSTRAINT fk_entrega_endereco FOREIGN KEY (id_endereco) REFERENCES ENDERECO(id_endereco),
    CONSTRAINT ck_entrega_status CHECK (status_entrega IN ('Aguardando', 'Em rota', 'Entregue', 'Cancelada')),
    CONSTRAINT ck_entrega_datas CHECK (
        data_hora_entrega IS NULL OR
        (data_hora_saida IS NOT NULL AND data_hora_entrega >= data_hora_saida)
    ),
    CONSTRAINT ck_entrega_final CHECK (status_entrega <> 'Entregue' OR data_hora_entrega IS NOT NULL)
) ENGINE=InnoDB;

CREATE TABLE DESPESA (
    id_despesa INT AUTO_INCREMENT PRIMARY KEY,
    descricao VARCHAR(255) NOT NULL,
    categoria VARCHAR(50) NOT NULL,
    data_despesa DATE NOT NULL DEFAULT (CURRENT_DATE),
    valor DECIMAL(10,2) NOT NULL,
    id_funcionario INT NOT NULL,
    CONSTRAINT fk_despesa_funcionario FOREIGN KEY (id_funcionario) REFERENCES FUNCIONARIO(id_funcionario),
    CONSTRAINT ck_despesa_valor CHECK (valor > 0)
) ENGINE=InnoDB;

CREATE INDEX idx_pedido_data_status ON PEDIDO (data_hora, status);
CREATE INDEX idx_pedido_canal ON PEDIDO (canal_atendimento);
CREATE INDEX idx_pagamento_pedido_status ON PAGAMENTO (id_pedido, status_pagamento);
CREATE INDEX idx_compra_data ON COMPRA (data_compra);
CREATE INDEX idx_despesa_data ON DESPESA (data_despesa);

